import{z as o,x as n,o as e,c as d,q as r,j as i,D as a,d as B,s as l,S as s,b as t}from"./chunks/framework.C8m1ZpeB.js";const _=JSON.parse('{"title":"自适应执行","description":"","frontmatter":{"title":"自适应执行","date":"2026-09-18T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/qo-adaptive-execution.md","filePath":"cs/qo-adaptive-execution.md","lastUpdated":1791413859000}'),p={name:"cs/qo-adaptive-execution.md"};function D(c,E,C,h,m,u){const A=n("Mermaid");return e(),d("div",null,[E[2]||(E[2]=r('<h1 id="自适应执行" tabindex="-1">自适应执行 <a class="header-anchor" href="#自适应执行" aria-label="Permalink to &quot;自适应执行&quot;">​</a></h1><div class="epigraph"><p>静态优化赌估计全对；自适应是给赌局加止损——在执行流的某个决策点允许改主意，而每次改主意都要付重新决策的税。</p><footer>—— 据 Kabra and DeWitt, 1998；Avnur and Hellerstein, 2000；Markl et al., 2004 整理</footer></div><p><a href="/cs/qo-plan-space">上一课</a>把静态空间收口：搜得再好，数字错了还是选错树。主干 <a href="/cs/adaptive-query-processing">自适应查询处理</a> 立了「监测—重优化」框架，<a href="/cs/learned-optimizer">学习型优化器</a> 管跨执行的记忆。本课深化单次执行内的工程谱系：决策点放在哪、能切换哪些东西、怎么防抖动与缓存放大。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>错有三种来源，纠偏点各不相同。参数错：同一句 SQL，主键点查与全表扫描共用一个通用计划，谁都跑不好。数据错：统计过期或倾斜，中间基数爆表。资源错：并发挤压，内存预算被砍，原计划选好的溢出方式不再合适。决策点沿时间轴展开：优化时（按参数重编译）、首行前（在候选计划里挑）、管道批间（发现误差换算子）、算子内（溢出方式与并行度）。乱放决策点的代价是切换税：已建的哈希表作废、编译重跑、中间结果物化；阈值太松救不了火，太紧则两个计划来回横跳，比不切还慢。</p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>参数敏感：把参数取值空间分箱，每箱存一个计划，执行时按参数落箱选计划——把「一次窥视定终身」改成「按类窥视」。通用与定制竞赛：前几次执行用定制计划，累计若干次后比较定制计划平均代价与通用计划代价，通用更便宜才切换。执行中重优化：在测量点比较实际与估计行数，比值超阈（如一个数量级）则物化已有中间结果，对剩余子树重跑枚举；正确性合同是同一快照、同一指称。算子内自适应：hybrid hash 在 build 中途发现超预算，就地转分区溢出，不惊动优化器。运行时过滤器：build 侧生成的布隆与取值范围下推到尚未执行的 probe 扫描，让后面的算子提前瘦身——这是静态计划上长出来的跨算子动态信息边，与 join 实现课的布隆同源，但强调「运行时生成、按本次数据现做」。</p>',7)),(e(),i(s,null,{default:a(()=>[l(A,{id:"mermaid-19",class:"mermaid",graph:"flowchart%20TD%0A%20%20OPT%5B%22%E4%BC%98%E5%8C%96%E6%97%B6%EF%BC%9A%E5%88%86%E7%AE%B1%E5%A4%9A%E8%AE%A1%E5%88%92%22%5D%20--%3E%20FIRST%5B%22%E9%A6%96%E8%A1%8C%E5%89%8D%EF%BC%9A%E9%80%9A%E7%94%A8%20vs%20%E5%AE%9A%E5%88%B6%E7%AB%9E%E8%B5%9B%22%5D%0A%20%20FIRST%20--%3E%20MID%5B%22%E6%89%B9%E9%97%B4%EF%BC%9A%E5%AE%9E%E9%99%85%2F%E4%BC%B0%E8%AE%A1%E6%AF%94%E8%B6%85%E9%98%88%E5%88%99%E9%87%8D%E4%BC%98%E5%8C%96%22%5D%0A%20%20MID%20--%3E%20INOP%5B%22%E7%AE%97%E5%AD%90%E5%86%85%EF%BC%9A%E6%BA%A2%E5%87%BA%E6%96%B9%E5%BC%8F%E5%88%87%E6%8D%A2%22%5D%0A%20%20INOP%20--%3E%20RT%5B%22%E8%BF%90%E8%A1%8C%E6%97%B6%E8%BF%87%E6%BB%A4%E5%99%A8%E4%B8%8B%E6%8E%A8%22%5D%0A%20%20RT%20--%3E%20FB%5B%22%E5%8F%8D%E9%A6%88%E5%86%99%E5%9B%9E%E7%9B%AE%E5%BD%95%22%5D%0A"})]),fallback:a(()=>[...E[0]||(E[0]=[B(" Loading... ",-1)])]),_:1})),E[3]||(E[3]=t("h2",{id:"机制",tabindex:"-1"},[B("机制 "),t("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),E[4]||(E[4]=t("p",null,"防抖动靠滞回：切换后锁定若干批，观察期不计入决策，避免在两个计划间振荡。反馈要写回：本次救火测得的实际基数进目录或反馈文件，让下一次静态优化受益；只救当次、不喂统计，等于同一个坑每天掉一次。成本核算定开关：短查询的监测与重优化税常超过执行本身，自适应是长管道的保险，不是全局默认——主干口径再次成立。缓存与自适应的接口：切换若发生在预编译语句上，改变的是本次执行的计划选择，缓存条目本身只在反馈写回后才更新。",-1)),(e(),i(s,null,{default:a(()=>[l(A,{id:"mermaid-26",class:"mermaid",graph:"flowchart%20TD%0A%20%20M%5B%22%E6%B5%8B%E9%87%8F%E7%82%B9%EF%BC%9A%E5%AE%9E%E9%99%85%E8%A1%8C%E6%95%B0%20vs%20%E4%BC%B0%E8%AE%A1%E8%A1%8C%E6%95%B0%22%5D%20--%3E%7C%22%E6%AF%94%E5%80%BC%E5%9C%A8%E9%98%88%E5%80%BC%E5%86%85%22%7C%20KEEP%5B%22%E7%BB%A7%E7%BB%AD%E5%BD%93%E5%89%8D%E8%AE%A1%E5%88%92%22%5D%0A%20%20M%20--%3E%7C%22%E6%AF%94%E5%80%BC%E8%B6%85%E9%98%88%22%7C%20SW%5B%22%E8%A7%A6%E5%8F%91%E5%88%87%E6%8D%A2%22%5D%0A%20%20SW%20--%3E%20MAT%5B%22%E7%89%A9%E5%8C%96%E5%B7%B2%E6%9C%89%E4%B8%AD%E9%97%B4%E7%BB%93%E6%9E%9C%22%5D%0A%20%20MAT%20--%3E%20RE%5B%22%E5%AF%B9%E5%89%A9%E4%BD%99%E5%AD%90%E6%A0%91%E9%87%8D%E8%B7%91%E6%9E%9A%E4%B8%BE%22%5D%0A%20%20SW%20--%3E%20LOCK%5B%22%E6%BB%9E%E5%9B%9E%EF%BC%9A%E9%94%81%E5%AE%9A%E8%8B%A5%E5%B9%B2%E6%89%B9%E4%B8%8D%E5%86%8D%E5%86%B3%E7%AD%96%22%5D%0A%20%20LOCK%20--%3E%20STABLE%5B%22%E8%A7%82%E5%AF%9F%E6%9C%9F%E7%BB%93%E6%9D%9F%E5%86%8D%E5%9B%9E%E5%88%B0%E6%B5%8B%E9%87%8F%E7%82%B9%22%5D%0A%20%20SW%20--%3E%20FB%5B%22%E5%AE%9E%E6%B5%8B%E5%9F%BA%E6%95%B0%E5%86%99%E5%9B%9E%E7%9B%AE%E5%BD%95%22%5D%0A%20%20FB%20--%3E%20NEXT%5B%22%E4%B8%8B%E6%AC%A1%E9%9D%99%E6%80%81%E4%BC%98%E5%8C%96%E5%8F%97%E7%9B%8A%22%5D%0A"})]),fallback:a(()=>[...E[1]||(E[1]=[B(" Loading... ",-1)])]),_:1})),E[5]||(E[5]=r('<p><span class="marginnote">PostgreSQL 的预编译语句缓存：前五次执行用定制计划，之后比较定制计划平均代价与通用计划代价，通用更便宜才切换；<code>plan_cache_mode</code> 可强制 auto、custom 或 generic。「竞赛」是写进源码的机制，不是比喻。</span></p><p><span class="marginnote">「参数分箱」就是把参数的取值范围切成几档（比如预估行数 0–100、100–1 万、1 万以上各一档），每档预先准备一份最合适的计划；执行时看参数落在哪一档，就拿哪一份计划，而不是拿一份「通吃」的计划硬套所有情况。</span></p><p><span class="marginnote">「比值超阈」可以代入具体的数：估计中间结果 1 万行、实际跑出 12 万行，比值 12 倍，超过 10 倍（一个数量级）的阈值，于是物化中间结果并对剩余子树重新枚举；若实际只有 1.2 万行，比值 1.2 倍，付一次切换税就不划算，继续跑。</span></p><p><span class="marginnote">初学者容易以为自适应是「免费纠错」——实际上每次改主意都要交税：已建好的哈希表作废、剩余子树重新优化、中间结果多一次物化。所以短查询宁可赌一份静态计划，自适应只留给长管道当保险。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>逐元组路由的 eddy 在生产 OLTP 里少见：逐元组决策的开销太大，本课点名不展开。提示与计划基线是反自适应的运维工具——DBA 冻结计划时，本课所有机制让位，两套机制要能共存而不互踩。自适应救的是单次执行；跨执行的记忆与漂移归学习型优化器，主干已讲。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>参数、数据、资源三类错对应不同决策点；切换有税，位置决定收益。</li><li>参数分箱与通用/定制竞赛治参数窥视；测量点重优化治数据错。</li><li>算子内切换与运行时过滤器是便宜的止损，不必惊动优化器。</li><li>滞回防抖，反馈写回喂下次；短查询默认关闭。</li><li>出处：Kabra and DeWitt, 1998；Avnur and Hellerstein, 2000；Markl et al., 2004。</li></ul>',8))])}const T=o(p,[["render",D]]);export{_ as __pageData,T as default};
